function bzAt(t, p0, c1, c2, p3){
  var u=1-t, a=u*u*u, b=3*u*u*t, c=3*u*t*t, d=t*t*t;
  return [a*p0[0]+b*c1[0]+c*c2[0]+d*p3[0], a*p0[1]+b*c1[1]+c*c2[1]+d*p3[1]];
}
function bzPolyline(pts, n){
  // pts: [p0,c1,c2,p3, c1,c2,p3, ...] -> k=(len-1)/3 segments
  n=n||60; var segs=(pts.length-1)/3, out=[];
  for(var s=0;s<segs;s++){
    var i=s*3, p0=pts[i], c1=pts[i+1], c2=pts[i+2], p3=pts[i+3];
    var start=s===0?0:1;
    for(var k=start;k<=n;k++){ out.push(bzAt(k/n, p0,c1,c2,p3)); }
  }
  return out;
}
function bzPath(pts){
  var segs=(pts.length-1)/3, d='M'+pts[0][0]+' '+pts[0][1];
  for(var s=0;s<segs;s++){ var i=s*3; d+=' C'+pts[i+1][0]+' '+pts[i+1][1]+' '+pts[i+2][0]+' '+pts[i+2][1]+' '+pts[i+3][0]+' '+pts[i+3][1]; }
  return d;
}
function bzSvg(pts){
  var d=bzPath(pts), poly='', handles='';
  for(var i=0;i<pts.length;i++){ poly+=(i?'L':'M')+pts[i][0]+' '+pts[i][1]; }
  for(var i=0;i<pts.length;i++){ handles+='<circle class="cp" data-i="'+i+'" cx="'+pts[i][0]+'" cy="'+pts[i][1]+'" r="'+(i%3===0?6:5)+'" fill="'+(i%3===0?'#5E6AD2':'#22D3EE')+'"/>'; }
  return '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 380 240" width="380" height="240">'
    +'<rect width="380" height="240" fill="#0A0A0B"/>'
    +'<path d="'+poly+'" fill="none" stroke="#3f3f46" stroke-width="1" stroke-dasharray="3 3"/>'
    +'<path d="'+d+'" fill="none" stroke="#5E6AD2" stroke-width="2.5"/>'+handles+'</svg>';
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { bzAt:bzAt, bzPolyline:bzPolyline, bzPath:bzPath, bzSvg:bzSvg };
}
if (typeof window !== 'undefined') {
  window.BezierForgePure = { bzAt:bzAt, bzPolyline:bzPolyline, bzPath:bzPath, bzSvg:bzSvg };
}
